-- Generated from constructor signatures. Do not edit; see source_imports.contracts.
CREATE FUNCTION atlas.valid_construction_record(method text, arguments jsonb)
RETURNS boolean LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $contract$
SELECT CASE method
WHEN 'geodesic_trace' THEN CASE WHEN jsonb_typeof(arguments) = 'object' THEN (
    arguments - ARRAY['source_ids', 'source_feature_id', 'feature_id', 'basis', 'points', 'max_step_metres', 'source_location']::text[] = '{}'::jsonb
    AND (arguments ? 'source_ids' AND COALESCE(CASE WHEN jsonb_typeof((arguments -> 'source_ids')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((arguments -> 'source_ids')) AS item0(value) WHERE NOT COALESCE((jsonb_typeof(item0.value) = 'string' AND atlas.nonblank(item0.value #>> '{}')), FALSE))) ELSE FALSE END, FALSE))
    AND (arguments ? 'source_feature_id' AND COALESCE((jsonb_typeof((arguments -> 'source_feature_id')) = 'string' AND atlas.nonblank((arguments -> 'source_feature_id') #>> '{}')), FALSE))
    AND (arguments ? 'feature_id' AND COALESCE((jsonb_typeof((arguments -> 'feature_id')) = 'string' AND atlas.nonblank((arguments -> 'feature_id') #>> '{}')), FALSE))
    AND (arguments ? 'basis' AND COALESCE((jsonb_typeof((arguments -> 'basis')) = 'string' AND atlas.nonblank((arguments -> 'basis') #>> '{}')), FALSE))
    AND (arguments ? 'points' AND COALESCE(CASE WHEN jsonb_typeof((arguments -> 'points')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((arguments -> 'points')) AS item0(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item0.value) = 'array' THEN (jsonb_array_length(item0.value) = 2 AND jsonb_typeof((item0.value -> 0)) = 'number' AND jsonb_typeof((item0.value -> 1)) = 'number') ELSE FALSE END, FALSE))) ELSE FALSE END, FALSE))
    AND (arguments ? 'max_step_metres' AND COALESCE(jsonb_typeof((arguments -> 'max_step_metres')) = 'number', FALSE))
    AND (NOT arguments ? 'source_location' OR COALESCE((CASE WHEN jsonb_typeof((arguments -> 'source_location')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((arguments -> 'source_location')) AS item0 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item0.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END OR jsonb_typeof((arguments -> 'source_location')) = 'string' OR jsonb_typeof((arguments -> 'source_location')) = 'null'), FALSE))) ELSE FALSE END
WHEN 'interpreted_geometry' THEN CASE WHEN jsonb_typeof(arguments) = 'object' THEN (
    arguments - ARRAY['source_ids', 'basis', 'selections']::text[] = '{}'::jsonb
    AND (arguments ? 'source_ids' AND COALESCE(CASE WHEN jsonb_typeof((arguments -> 'source_ids')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((arguments -> 'source_ids')) AS item0(value) WHERE NOT COALESCE((jsonb_typeof(item0.value) = 'string' AND atlas.nonblank(item0.value #>> '{}')), FALSE))) ELSE FALSE END, FALSE))
    AND (arguments ? 'basis' AND COALESCE((jsonb_typeof((arguments -> 'basis')) = 'string' AND atlas.nonblank((arguments -> 'basis') #>> '{}')), FALSE))
    AND (arguments ? 'selections' AND COALESCE(CASE WHEN jsonb_typeof((arguments -> 'selections')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((arguments -> 'selections')) AS item0(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item0.value) = 'object' THEN (
    item0.value - ARRAY['feature_id', 'geometry']::text[] = '{}'::jsonb
    AND (item0.value ? 'feature_id' AND COALESCE((jsonb_typeof((item0.value -> 'feature_id')) = 'string' AND atlas.nonblank((item0.value -> 'feature_id') #>> '{}')), FALSE))
    AND (item0.value ? 'geometry' AND COALESCE((CASE WHEN jsonb_typeof((item0.value -> 'geometry')) = 'object' THEN (
    (item0.value -> 'geometry') - ARRAY['type', 'coordinates']::text[] = '{}'::jsonb
    AND ((item0.value -> 'geometry') ? 'type' AND COALESCE((((item0.value -> 'geometry') -> 'type') = '"Point"'::jsonb), FALSE))
    AND ((item0.value -> 'geometry') ? 'coordinates' AND COALESCE(CASE WHEN jsonb_typeof(((item0.value -> 'geometry') -> 'coordinates')) = 'array' THEN (jsonb_array_length(((item0.value -> 'geometry') -> 'coordinates')) = 2 AND jsonb_typeof((((item0.value -> 'geometry') -> 'coordinates') -> 0)) = 'number' AND jsonb_typeof((((item0.value -> 'geometry') -> 'coordinates') -> 1)) = 'number') ELSE FALSE END, FALSE))) ELSE FALSE END OR CASE WHEN jsonb_typeof((item0.value -> 'geometry')) = 'object' THEN (
    (item0.value -> 'geometry') - ARRAY['type', 'coordinates']::text[] = '{}'::jsonb
    AND ((item0.value -> 'geometry') ? 'type' AND COALESCE((((item0.value -> 'geometry') -> 'type') = '"Polygon"'::jsonb), FALSE))
    AND ((item0.value -> 'geometry') ? 'coordinates' AND COALESCE(CASE WHEN jsonb_typeof(((item0.value -> 'geometry') -> 'coordinates')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements(((item0.value -> 'geometry') -> 'coordinates')) AS item3(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item3.value) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements(item3.value) AS item4(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item4.value) = 'array' THEN (jsonb_array_length(item4.value) = 2 AND jsonb_typeof((item4.value -> 0)) = 'number' AND jsonb_typeof((item4.value -> 1)) = 'number') ELSE FALSE END, FALSE))) ELSE FALSE END, FALSE))) ELSE FALSE END, FALSE))) ELSE FALSE END), FALSE))) ELSE FALSE END, FALSE))) ELSE FALSE END, FALSE))) ELSE FALSE END
WHEN 'osm_way_chain' THEN CASE WHEN jsonb_typeof(arguments) = 'object' THEN (
    arguments - ARRAY['source_id', 'feature_id', 'source_feature_id', 'basis', 'before', 'after', 'max_step_metres', 'evidence_source_ids']::text[] = '{}'::jsonb
    AND (arguments ? 'source_id' AND COALESCE((jsonb_typeof((arguments -> 'source_id')) = 'string' AND atlas.nonblank((arguments -> 'source_id') #>> '{}')), FALSE))
    AND (arguments ? 'feature_id' AND COALESCE((jsonb_typeof((arguments -> 'feature_id')) = 'string' AND atlas.nonblank((arguments -> 'feature_id') #>> '{}')), FALSE))
    AND (arguments ? 'source_feature_id' AND COALESCE((jsonb_typeof((arguments -> 'source_feature_id')) = 'string' AND atlas.nonblank((arguments -> 'source_feature_id') #>> '{}')), FALSE))
    AND (arguments ? 'basis' AND COALESCE((jsonb_typeof((arguments -> 'basis')) = 'string' AND atlas.nonblank((arguments -> 'basis') #>> '{}')), FALSE))
    AND (NOT arguments ? 'before' OR COALESCE((CASE WHEN jsonb_typeof((arguments -> 'before')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((arguments -> 'before')) AS item0(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item0.value) = 'array' THEN (jsonb_array_length(item0.value) = 2 AND jsonb_typeof((item0.value -> 0)) = 'number' AND jsonb_typeof((item0.value -> 1)) = 'number') ELSE FALSE END, FALSE))) ELSE FALSE END OR jsonb_typeof((arguments -> 'before')) = 'null'), FALSE))
    AND (NOT arguments ? 'after' OR COALESCE((CASE WHEN jsonb_typeof((arguments -> 'after')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((arguments -> 'after')) AS item0(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item0.value) = 'array' THEN (jsonb_array_length(item0.value) = 2 AND jsonb_typeof((item0.value -> 0)) = 'number' AND jsonb_typeof((item0.value -> 1)) = 'number') ELSE FALSE END, FALSE))) ELSE FALSE END OR jsonb_typeof((arguments -> 'after')) = 'null'), FALSE))
    AND (NOT arguments ? 'max_step_metres' OR COALESCE(jsonb_typeof((arguments -> 'max_step_metres')) = 'number', FALSE))
    AND (NOT arguments ? 'evidence_source_ids' OR COALESCE((CASE WHEN jsonb_typeof((arguments -> 'evidence_source_ids')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((arguments -> 'evidence_source_ids')) AS item0(value) WHERE NOT COALESCE((jsonb_typeof(item0.value) = 'string' AND atlas.nonblank(item0.value #>> '{}')), FALSE))) ELSE FALSE END OR jsonb_typeof((arguments -> 'evidence_source_ids')) = 'null'), FALSE))) ELSE FALSE END
WHEN 's130_areas' THEN CASE WHEN jsonb_typeof(arguments) = 'object' THEN (
    arguments - ARRAY['source_id', 'basis', 'gml_member', 'gml_sha256', 'selections']::text[] = '{}'::jsonb
    AND (arguments ? 'source_id' AND COALESCE((jsonb_typeof((arguments -> 'source_id')) = 'string' AND atlas.nonblank((arguments -> 'source_id') #>> '{}')), FALSE))
    AND (arguments ? 'basis' AND COALESCE((jsonb_typeof((arguments -> 'basis')) = 'string' AND atlas.nonblank((arguments -> 'basis') #>> '{}')), FALSE))
    AND (arguments ? 'gml_member' AND COALESCE((jsonb_typeof((arguments -> 'gml_member')) = 'string' AND atlas.nonblank((arguments -> 'gml_member') #>> '{}')), FALSE))
    AND (arguments ? 'gml_sha256' AND COALESCE((jsonb_typeof((arguments -> 'gml_sha256')) = 'string' AND atlas.nonblank((arguments -> 'gml_sha256') #>> '{}')), FALSE))
    AND (arguments ? 'selections' AND COALESCE(CASE WHEN jsonb_typeof((arguments -> 'selections')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((arguments -> 'selections')) AS item0(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item0.value) = 'object' THEN (
    item0.value - ARRAY['feature_id', 'source_feature_id']::text[] = '{}'::jsonb
    AND (item0.value ? 'feature_id' AND COALESCE((jsonb_typeof((item0.value -> 'feature_id')) = 'string' AND atlas.nonblank((item0.value -> 'feature_id') #>> '{}')), FALSE))
    AND (item0.value ? 'source_feature_id' AND COALESCE(((jsonb_typeof((item0.value -> 'source_feature_id')) = 'string' AND atlas.nonblank((item0.value -> 'source_feature_id') #>> '{}')) OR CASE WHEN jsonb_typeof((item0.value -> 'source_feature_id')) = 'number' THEN trunc(((item0.value -> 'source_feature_id') #>> '{}')::numeric) = ((item0.value -> 'source_feature_id') #>> '{}')::numeric ELSE FALSE END), FALSE))) ELSE FALSE END, FALSE))) ELSE FALSE END, FALSE))) ELSE FALSE END
WHEN 'selected_osm_features' THEN CASE WHEN jsonb_typeof(arguments) = 'object' THEN (
    arguments - ARRAY['source_id', 'basis', 'selections']::text[] = '{}'::jsonb
    AND (arguments ? 'source_id' AND COALESCE((jsonb_typeof((arguments -> 'source_id')) = 'string' AND atlas.nonblank((arguments -> 'source_id') #>> '{}')), FALSE))
    AND (arguments ? 'basis' AND COALESCE((jsonb_typeof((arguments -> 'basis')) = 'string' AND atlas.nonblank((arguments -> 'basis') #>> '{}')), FALSE))
    AND (arguments ? 'selections' AND COALESCE(CASE WHEN jsonb_typeof((arguments -> 'selections')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((arguments -> 'selections')) AS item0(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item0.value) = 'object' THEN (
    item0.value - ARRAY['feature_id', 'source_feature_id', 'object_type', 'object_version', 'expected_tags', 'parent_relation', 'ignored_member_roles', 'ring_anchors', 'holes', 'geometry_type']::text[] = '{}'::jsonb
    AND (item0.value ? 'feature_id' AND COALESCE((jsonb_typeof((item0.value -> 'feature_id')) = 'string' AND atlas.nonblank((item0.value -> 'feature_id') #>> '{}')), FALSE))
    AND (item0.value ? 'source_feature_id' AND COALESCE(((jsonb_typeof((item0.value -> 'source_feature_id')) = 'string' AND atlas.nonblank((item0.value -> 'source_feature_id') #>> '{}')) OR CASE WHEN jsonb_typeof((item0.value -> 'source_feature_id')) = 'number' THEN trunc(((item0.value -> 'source_feature_id') #>> '{}')::numeric) = ((item0.value -> 'source_feature_id') #>> '{}')::numeric ELSE FALSE END), FALSE))
    AND (item0.value ? 'object_type' AND COALESCE(((item0.value -> 'object_type') = '"node"'::jsonb OR (item0.value -> 'object_type') = '"way"'::jsonb OR (item0.value -> 'object_type') = '"relation"'::jsonb), FALSE))
    AND (item0.value ? 'object_version' AND COALESCE(((jsonb_typeof((item0.value -> 'object_version')) = 'string' AND atlas.nonblank((item0.value -> 'object_version') #>> '{}')) OR CASE WHEN jsonb_typeof((item0.value -> 'object_version')) = 'number' THEN trunc(((item0.value -> 'object_version') #>> '{}')::numeric) = ((item0.value -> 'object_version') #>> '{}')::numeric ELSE FALSE END), FALSE))
    AND (NOT item0.value ? 'expected_tags' OR COALESCE(CASE WHEN jsonb_typeof((item0.value -> 'expected_tags')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((item0.value -> 'expected_tags')) AS item2 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item2.key)) = 'string' AND jsonb_typeof(item2.value) = 'string'), FALSE)) ELSE FALSE END, FALSE))
    AND (NOT item0.value ? 'parent_relation' OR COALESCE(CASE WHEN jsonb_typeof((item0.value -> 'parent_relation')) = 'object' THEN (
    (item0.value -> 'parent_relation') - ARRAY['id', 'version', 'role', 'expected_tags']::text[] = '{}'::jsonb
    AND ((item0.value -> 'parent_relation') ? 'id' AND COALESCE(((jsonb_typeof(((item0.value -> 'parent_relation') -> 'id')) = 'string' AND atlas.nonblank(((item0.value -> 'parent_relation') -> 'id') #>> '{}')) OR CASE WHEN jsonb_typeof(((item0.value -> 'parent_relation') -> 'id')) = 'number' THEN trunc((((item0.value -> 'parent_relation') -> 'id') #>> '{}')::numeric) = (((item0.value -> 'parent_relation') -> 'id') #>> '{}')::numeric ELSE FALSE END), FALSE))
    AND ((item0.value -> 'parent_relation') ? 'version' AND COALESCE(((jsonb_typeof(((item0.value -> 'parent_relation') -> 'version')) = 'string' AND atlas.nonblank(((item0.value -> 'parent_relation') -> 'version') #>> '{}')) OR CASE WHEN jsonb_typeof(((item0.value -> 'parent_relation') -> 'version')) = 'number' THEN trunc((((item0.value -> 'parent_relation') -> 'version') #>> '{}')::numeric) = (((item0.value -> 'parent_relation') -> 'version') #>> '{}')::numeric ELSE FALSE END), FALSE))
    AND ((item0.value -> 'parent_relation') ? 'role' AND COALESCE(jsonb_typeof(((item0.value -> 'parent_relation') -> 'role')) = 'string', FALSE))
    AND (NOT (item0.value -> 'parent_relation') ? 'expected_tags' OR COALESCE(CASE WHEN jsonb_typeof(((item0.value -> 'parent_relation') -> 'expected_tags')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each(((item0.value -> 'parent_relation') -> 'expected_tags')) AS item3 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item3.key)) = 'string' AND jsonb_typeof(item3.value) = 'string'), FALSE)) ELSE FALSE END, FALSE))) ELSE FALSE END, FALSE))
    AND (NOT item0.value ? 'ignored_member_roles' OR COALESCE(CASE WHEN jsonb_typeof((item0.value -> 'ignored_member_roles')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((item0.value -> 'ignored_member_roles')) AS item2(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item2.value) = 'array' THEN (jsonb_array_length(item2.value) = 2 AND ((item2.value -> 0) = '"n"'::jsonb OR (item2.value -> 0) = '"w"'::jsonb OR (item2.value -> 0) = '"r"'::jsonb) AND jsonb_typeof((item2.value -> 1)) = 'string') ELSE FALSE END, FALSE))) ELSE FALSE END, FALSE))
    AND (NOT item0.value ? 'ring_anchors' OR COALESCE(CASE WHEN jsonb_typeof((item0.value -> 'ring_anchors')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((item0.value -> 'ring_anchors')) AS item2(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item2.value) = 'object' THEN (
    item2.value - ARRAY['node_id', 'way_id', 'node_version', 'expected_tags']::text[] = '{}'::jsonb
    AND (item2.value ? 'node_id' AND COALESCE(((jsonb_typeof((item2.value -> 'node_id')) = 'string' AND atlas.nonblank((item2.value -> 'node_id') #>> '{}')) OR CASE WHEN jsonb_typeof((item2.value -> 'node_id')) = 'number' THEN trunc(((item2.value -> 'node_id') #>> '{}')::numeric) = ((item2.value -> 'node_id') #>> '{}')::numeric ELSE FALSE END), FALSE))
    AND (item2.value ? 'way_id' AND COALESCE(((jsonb_typeof((item2.value -> 'way_id')) = 'string' AND atlas.nonblank((item2.value -> 'way_id') #>> '{}')) OR CASE WHEN jsonb_typeof((item2.value -> 'way_id')) = 'number' THEN trunc(((item2.value -> 'way_id') #>> '{}')::numeric) = ((item2.value -> 'way_id') #>> '{}')::numeric ELSE FALSE END), FALSE))
    AND (item2.value ? 'node_version' AND COALESCE(((jsonb_typeof((item2.value -> 'node_version')) = 'string' AND atlas.nonblank((item2.value -> 'node_version') #>> '{}')) OR CASE WHEN jsonb_typeof((item2.value -> 'node_version')) = 'number' THEN trunc(((item2.value -> 'node_version') #>> '{}')::numeric) = ((item2.value -> 'node_version') #>> '{}')::numeric ELSE FALSE END), FALSE))
    AND (item2.value ? 'expected_tags' AND COALESCE(CASE WHEN jsonb_typeof((item2.value -> 'expected_tags')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((item2.value -> 'expected_tags')) AS item4 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item4.key)) = 'string' AND jsonb_typeof(item4.value) = 'string'), FALSE)) ELSE FALSE END, FALSE))) ELSE FALSE END, FALSE))) ELSE FALSE END, FALSE))
    AND (NOT item0.value ? 'holes' OR COALESCE(((item0.value -> 'holes') = '"preserve"'::jsonb OR (item0.value -> 'holes') = '"outer_envelope"'::jsonb), FALSE))
    AND (NOT item0.value ? 'geometry_type' OR COALESCE(((item0.value -> 'geometry_type') = '"Polygon"'::jsonb OR (item0.value -> 'geometry_type') = '"MultiPolygon"'::jsonb), FALSE))) ELSE FALSE END, FALSE))) ELSE FALSE END, FALSE))) ELSE FALSE END
WHEN 'selected_vector_features' THEN CASE WHEN jsonb_typeof(arguments) = 'object' THEN (
    arguments - ARRAY['source_id', 'basis', 'id_field', 'selections', 'member', 'layer', 'coordinate_operation']::text[] = '{}'::jsonb
    AND (arguments ? 'source_id' AND COALESCE((jsonb_typeof((arguments -> 'source_id')) = 'string' AND atlas.nonblank((arguments -> 'source_id') #>> '{}')), FALSE))
    AND (arguments ? 'basis' AND COALESCE((jsonb_typeof((arguments -> 'basis')) = 'string' AND atlas.nonblank((arguments -> 'basis') #>> '{}')), FALSE))
    AND (arguments ? 'id_field' AND COALESCE((jsonb_typeof((arguments -> 'id_field')) = 'string' AND atlas.nonblank((arguments -> 'id_field') #>> '{}')), FALSE))
    AND (arguments ? 'selections' AND COALESCE(CASE WHEN jsonb_typeof((arguments -> 'selections')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((arguments -> 'selections')) AS item0(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item0.value) = 'object' THEN (
    item0.value - ARRAY['feature_id', 'source_feature_id', 'collection', 'expected_feature_count', 'polygon_containing', 'holes']::text[] = '{}'::jsonb
    AND (item0.value ? 'feature_id' AND COALESCE((jsonb_typeof((item0.value -> 'feature_id')) = 'string' AND atlas.nonblank((item0.value -> 'feature_id') #>> '{}')), FALSE))
    AND (item0.value ? 'source_feature_id' AND COALESCE(((jsonb_typeof((item0.value -> 'source_feature_id')) = 'string' AND atlas.nonblank((item0.value -> 'source_feature_id') #>> '{}')) OR CASE WHEN jsonb_typeof((item0.value -> 'source_feature_id')) = 'number' THEN trunc(((item0.value -> 'source_feature_id') #>> '{}')::numeric) = ((item0.value -> 'source_feature_id') #>> '{}')::numeric ELSE FALSE END), FALSE))
    AND (NOT item0.value ? 'collection' OR COALESCE(jsonb_typeof((item0.value -> 'collection')) = 'boolean', FALSE))
    AND (NOT item0.value ? 'expected_feature_count' OR COALESCE(CASE WHEN jsonb_typeof((item0.value -> 'expected_feature_count')) = 'number' THEN trunc(((item0.value -> 'expected_feature_count') #>> '{}')::numeric) = ((item0.value -> 'expected_feature_count') #>> '{}')::numeric ELSE FALSE END, FALSE))
    AND (NOT item0.value ? 'polygon_containing' OR COALESCE(CASE WHEN jsonb_typeof((item0.value -> 'polygon_containing')) = 'array' THEN (jsonb_array_length((item0.value -> 'polygon_containing')) = 2 AND jsonb_typeof(((item0.value -> 'polygon_containing') -> 0)) = 'number' AND jsonb_typeof(((item0.value -> 'polygon_containing') -> 1)) = 'number') ELSE FALSE END, FALSE))
    AND (NOT item0.value ? 'holes' OR COALESCE(((item0.value -> 'holes') = '"preserve"'::jsonb OR (item0.value -> 'holes') = '"outer_envelope"'::jsonb), FALSE))) ELSE FALSE END, FALSE))) ELSE FALSE END, FALSE))
    AND (NOT arguments ? 'member' OR COALESCE(((jsonb_typeof((arguments -> 'member')) = 'string' AND atlas.nonblank((arguments -> 'member') #>> '{}')) OR jsonb_typeof((arguments -> 'member')) = 'null'), FALSE))
    AND (NOT arguments ? 'layer' OR COALESCE(((jsonb_typeof((arguments -> 'layer')) = 'string' AND atlas.nonblank((arguments -> 'layer') #>> '{}')) OR jsonb_typeof((arguments -> 'layer')) = 'null'), FALSE))
    AND (NOT arguments ? 'coordinate_operation' OR COALESCE(((jsonb_typeof((arguments -> 'coordinate_operation')) = 'string' AND atlas.nonblank((arguments -> 'coordinate_operation') #>> '{}')) OR jsonb_typeof((arguments -> 'coordinate_operation')) = 'null'), FALSE))) ELSE FALSE END
WHEN 'watershed_boundary' THEN CASE WHEN jsonb_typeof(arguments) = 'object' THEN (
    arguments - ARRAY['feature_id', 'basis', 'sources', 'lines', 'sections', 'joins', 'start', 'end', 'terrains', 'evidence_sources', 'geographic_choices']::text[] = '{}'::jsonb
    AND (arguments ? 'feature_id' AND COALESCE((jsonb_typeof((arguments -> 'feature_id')) = 'string' AND atlas.nonblank((arguments -> 'feature_id') #>> '{}')), FALSE))
    AND (arguments ? 'basis' AND COALESCE((jsonb_typeof((arguments -> 'basis')) = 'string' AND atlas.nonblank((arguments -> 'basis') #>> '{}')), FALSE))
    AND (arguments ? 'sources' AND COALESCE(CASE WHEN jsonb_typeof((arguments -> 'sources')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((arguments -> 'sources')) AS item0 WHERE NOT COALESCE(((jsonb_typeof(to_jsonb(item0.key)) = 'string' AND atlas.nonblank(to_jsonb(item0.key) #>> '{}')) AND ((jsonb_typeof(item0.value) = 'string' AND atlas.nonblank(item0.value #>> '{}')) OR CASE WHEN jsonb_typeof(item0.value) = 'object' THEN (
    item0.value - ARRAY['parts', 'sha256', 'size_bytes', 'filename']::text[] = '{}'::jsonb
    AND (item0.value ? 'parts' AND COALESCE(CASE WHEN jsonb_typeof((item0.value -> 'parts')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((item0.value -> 'parts')) AS item2(value) WHERE NOT COALESCE((jsonb_typeof(item2.value) = 'string' AND atlas.nonblank(item2.value #>> '{}')), FALSE))) ELSE FALSE END, FALSE))
    AND (item0.value ? 'sha256' AND COALESCE((jsonb_typeof((item0.value -> 'sha256')) = 'string' AND atlas.nonblank((item0.value -> 'sha256') #>> '{}')), FALSE))
    AND (item0.value ? 'size_bytes' AND COALESCE(CASE WHEN jsonb_typeof((item0.value -> 'size_bytes')) = 'number' THEN trunc(((item0.value -> 'size_bytes') #>> '{}')::numeric) = ((item0.value -> 'size_bytes') #>> '{}')::numeric ELSE FALSE END, FALSE))
    AND (item0.value ? 'filename' AND COALESCE((jsonb_typeof((item0.value -> 'filename')) = 'string' AND atlas.nonblank((item0.value -> 'filename') #>> '{}')), FALSE))) ELSE FALSE END)), FALSE)) ELSE FALSE END, FALSE))
    AND (arguments ? 'lines' AND COALESCE(CASE WHEN jsonb_typeof((arguments -> 'lines')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((arguments -> 'lines')) AS item0 WHERE NOT COALESCE(((jsonb_typeof(to_jsonb(item0.key)) = 'string' AND atlas.nonblank(to_jsonb(item0.key) #>> '{}')) AND CASE WHEN jsonb_typeof(item0.value) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements(item0.value) AS item1(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item1.value) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each(item1.value) AS item2 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item2.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END, FALSE))) ELSE FALSE END), FALSE)) ELSE FALSE END, FALSE))
    AND (arguments ? 'sections' AND COALESCE(CASE WHEN jsonb_typeof((arguments -> 'sections')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((arguments -> 'sections')) AS item0(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item0.value) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each(item0.value) AS item1 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item1.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END, FALSE))) ELSE FALSE END, FALSE))
    AND (arguments ? 'joins' AND COALESCE(CASE WHEN jsonb_typeof((arguments -> 'joins')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((arguments -> 'joins')) AS item0(value) WHERE NOT COALESCE(CASE WHEN jsonb_typeof(item0.value) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each(item0.value) AS item1 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item1.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END, FALSE))) ELSE FALSE END, FALSE))
    AND (arguments ? 'start' AND COALESCE(CASE WHEN jsonb_typeof((arguments -> 'start')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((arguments -> 'start')) AS item0 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item0.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END, FALSE))
    AND (arguments ? 'end' AND COALESCE(CASE WHEN jsonb_typeof((arguments -> 'end')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((arguments -> 'end')) AS item0 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item0.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END, FALSE))
    AND (NOT arguments ? 'terrains' OR COALESCE((CASE WHEN jsonb_typeof((arguments -> 'terrains')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((arguments -> 'terrains')) AS item0 WHERE NOT COALESCE(((jsonb_typeof(to_jsonb(item0.key)) = 'string' AND atlas.nonblank(to_jsonb(item0.key) #>> '{}')) AND CASE WHEN jsonb_typeof(item0.value) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each(item0.value) AS item1 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item1.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END), FALSE)) ELSE FALSE END OR jsonb_typeof((arguments -> 'terrains')) = 'null'), FALSE))
    AND (NOT arguments ? 'evidence_sources' OR COALESCE((CASE WHEN jsonb_typeof((arguments -> 'evidence_sources')) = 'array' THEN (NOT EXISTS (SELECT 1 FROM jsonb_array_elements((arguments -> 'evidence_sources')) AS item0(value) WHERE NOT COALESCE((jsonb_typeof(item0.value) = 'string' AND atlas.nonblank(item0.value #>> '{}')), FALSE))) ELSE FALSE END OR jsonb_typeof((arguments -> 'evidence_sources')) = 'null'), FALSE))
    AND (NOT arguments ? 'geographic_choices' OR COALESCE((CASE WHEN jsonb_typeof((arguments -> 'geographic_choices')) = 'object' THEN NOT EXISTS (SELECT 1 FROM jsonb_each((arguments -> 'geographic_choices')) AS item0 WHERE NOT COALESCE((jsonb_typeof(to_jsonb(item0.key)) = 'string' AND TRUE), FALSE)) ELSE FALSE END OR jsonb_typeof((arguments -> 'geographic_choices')) = 'null'), FALSE))) ELSE FALSE END
ELSE FALSE END;
$contract$;
ALTER TABLE atlas.construction_records ADD CONSTRAINT construction_arguments_valid
CHECK (atlas.valid_construction_record(method, arguments));

CREATE FUNCTION atlas.construction_source_ids(method text, arguments jsonb)
RETURNS SETOF text LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $sources$
SELECT DISTINCT value #>> '{}' FROM unnest(CASE method
WHEN 'geodesic_trace' THEN ARRAY['lax $."source_ids"[*]']::jsonpath[]
WHEN 'interpreted_geometry' THEN ARRAY['lax $."source_ids"[*]']::jsonpath[]
WHEN 'osm_way_chain' THEN ARRAY['lax $."evidence_source_ids"[*]','lax $."source_id"']::jsonpath[]
WHEN 's130_areas' THEN ARRAY['lax $."source_id"']::jsonpath[]
WHEN 'selected_osm_features' THEN ARRAY['lax $."source_id"']::jsonpath[]
WHEN 'selected_vector_features' THEN ARRAY['lax $."source_id"']::jsonpath[]
WHEN 'watershed_boundary' THEN ARRAY['lax $."evidence_sources"[*]','lax $."sources".*','lax $."sources".*."parts"[*]']::jsonpath[]
ELSE ARRAY[]::jsonpath[] END) AS paths(path)
CROSS JOIN LATERAL jsonb_path_query(arguments,path,'{}'::jsonb,true) AS refs(value)
WHERE jsonb_typeof(value)='string';
$sources$;
